contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash, bool doFirst, uint256 amount) public payable {
        require(amount > 0 && amount < type(uint256).max / 2);
        require(address(this).balance >= amount);

        bool reverted1;
        bool reverted2;

        if (doFirst) {
            try c.lockInGuess{value: amount}(hash) {
                reverted1 = false;
            } catch {
                reverted1 = true;
            }

            try c.lockInGuess{value: amount}(hash) {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }

            assert(!reverted1 ? reverted2 : (address(c).balance == 0));
        } else {
            bool reverted0;
            try c.lockInGuess{value: amount}(hash) {
                reverted0 = false;
            } catch {
                reverted0 = true;
            }
            assert(reverted0 == (amount != 1 ether));
        }
    }

    receive() external payable {}
}

